def prod_signs(arr):
    if not arr:
        return None

    sign_product = 1
    magnitude_sum = 0

    for num in arr:
        magnitude_sum += abs(num)
        if num == 0:
            sign_product = 0
        elif num < 0:
            sign_product *= -1

    return sign_product * magnitude_sum
```

